def solve(n):
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0:2] = [False, False]
    count = 0
    for i in range(2, n):
        if sieve[i]:
            count += 1
            step = i
            start = i * i
            if start >= n:
                continue
            sieve[start:n:step] = [False] * ((n - start - 1) // step + 1)
    return count

