def solve(m):
    # Compute determinant of an integer matrix using Bareiss algorithm (fraction-free Gaussian elimination).
    # m is a list of lists, square matrix. Empty matrix returns 1.
    if not m:
        return 1
    n = len(m)
    # copy matrix to avoid mutating input
    a = [row[:] for row in m]
    sign = 1
    prev = 1
    for k in range(n - 1):
        # pivot if zero
        if a[k][k] == 0:
            # find a non-zero pivot below
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    a[k], a[i] = a[i], a[k]
                    sign = -sign
                    break
            else:
                return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = a[k][k]
    return sign * a[n - 1][n - 1]

