    import copy
    def det_recursive(mat):
        n = len(mat)
        if n == 0:
            return 1
        if n == 1:
            return mat[0][0]
        if n == 2:
            return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
        total = 0
        for col in range(n):
            # build submatrix
            sub = [row[:col] + row[col+1:] for row in mat[1:]]
            sign = -1 if col % 2 else 1
            total += sign * mat[0][col] * det_recursive(sub)
        return total
    n = len(m)
    if n <= 6:
        return det_recursive([row[:] for row in m])
    # else use Bareiss
    if n == 0:
        return 1
    a = [row[:] for row in m]
