def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than *n*.
    Uses an efficient Sieve of Eratosthenes with a bytearray for memory.
    Handles n <= 2 and negative inputs by returning 0.
    """
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    limit = int(n ** 0.5) + 1
    for i in range(2, limit):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start:n:step] = b'\x00' * ((n - start - 1) // step + 1)
    return sum(sieve)

