def solve(n) -> int:
    """Return the number of primes strictly less than *n*.
    Handles non‑int or negative inputs by treating them as 0.
    Uses an optimized odd‑only sieve for moderate n (<=5_000_000).
    For larger n it falls back to a simple trial‑division count which, while slower,
    avoids huge memory consumption and still produces the correct result.
    """
    # Validate and normalize input
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # For moderate size use memory‑efficient sieve (odd numbers only)
    if n <= 5_000_000:
        # Count prime 2
        count = 1
        size = n // 2  # number of odd candidates < n
        sieve = bytearray(size)  # 0 = potential prime, 1 = composite
        limit = int(n ** 0.5) + 1
        for i in range(3, limit, 2):
            if not sieve[i // 2]:
                step = i * 2
                start = i * i
                for j in range(start, n, step):
                    sieve[j // 2] = 1
        # Count odd primes
        count += sum(1 for i in range(1, size) if not sieve[i])
        return count
    # Fallback for very large n: trial division (still correct, albeit slower)
    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        r = int(x ** 0.5)
        f = 3
        while f <= r:
            if x % f == 0:
                return False
            f += 2
        return True
    cnt = 0
    for num in range(2, n):
        if is_prime(num):
            cnt += 1
    return cnt

