def solve(path):
    """Simplify a Unix-style absolute path.
    Returns the canonical path as a string.
    """
    if not path:
        # Edge case: empty input, return empty string (as a safe default)
        return ''
    parts = path.split('/')
    stack = []
    for p in parts:
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                stack.pop()
        else:
            stack.append(p)
    # If stack is empty, the simplified path is the root '/'
    return '/' + '/'.join(stack) if stack else '/'

