    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p:
            return False
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
